<h3><?=e($iaText('Vorhandene Ausgabe zuordnen'))?></h3><p><?=e($iaText('Eine bereits vorhandene Ausgabe suchen und beide Originale vor der Zuordnung vergleichen. Es wird keine neue Ausgabe oder Zahlung angelegt.'))?></p>
<p><a class="btn btn-outline theme-secondary" data-invoice-assignment-original href="<?=e(url($ia['original']+['inbox_read'=>bin2hex(random_bytes(8))]))?>"><?=e($iaText('Zur ursprünglichen Rechnung'))?></a></p>
