<?php if($ia['raw']):?><h5><?=e($iaText('Angaben'))?></h5><dl><?php foreach($ia['raw']as$field=>$value):?><dt><?=e($iaText($field))?></dt><dd data-invoice-assignment-raw="<?=e($field)?>"><?php if(!is_string($value)):?><span><?=e($iaText('Mehrteilige Angabe'))?></span><?php endif;?><pre><?=e(is_string($value)?$value:json_encode($value,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_PARTIAL_OUTPUT_ON_ERROR))?></pre></dd><?php endforeach;?></dl><?php endif;?>
<?php if($ia['refresh']):?><p><a class="btn btn-outline theme-secondary" data-invoice-assignment-refresh href="<?=e($iaUrl($ia['refresh']))?>"><?=e($iaText('Dieselbe Rechnung und Ausgabe im aktuellen Stand lesen'))?></a></p><?php endif;?>
<?php if($ia['list']):?><a class="btn btn-outline theme-secondary" data-invoice-assignment-list href="<?=e($iaUrl($ia['list']))?>"><?=e($iaText($ia['list_keeps_query']?'Ausgabenliste mit dieser Suche neu öffnen':'Ausgabensuche ohne Filter bewusst öffnen'))?></a><?php endif;?>
<?php foreach($ia['document']['entry_links']??[]as$existingLink):?><p><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'finance','tab'=>'receipts','entry'=>$existingLink['source_id']]))?>"><?=e($iaText('Bereits zugeordneten Beleg öffnen'))?>: <?=e($existingLink['label'])?></a></p><?php endforeach;?>
</section>
<?php elseif($ia['state']==='review'):$iaExpense=$ia['expense'];?>
