<a class="btn btn-outline theme-secondary" data-invoice-assignment-list href="<?=e($iaUrl($ia['list']))?>"><?=e($iaText('Auswahl ändern'))?></a></section>
<?php else:$iaCatalogue=$ia['catalogue'];$iaContext=$ia['list'];?>
