<p role="status" data-invoice-assignment-count><?=e($iaText('{count} passende Ausgaben · {first}–{last} angezeigt',['count'=>(string)$iaCatalogue['total'],'first'=>$iaCatalogue['total']?(string)(($iaCatalogue['page']-1)*6+1):'0','last'=>(string)min($iaCatalogue['total'],$iaCatalogue['page']*6)]))?></p>
<?php foreach($iaCatalogue['rows']as$iaExpense):?><article class="card" data-invoice-assignment-candidate="<?=e($iaExpense['id'])?>"><h4><?=e($iaExpense['display_number'].' · '.$iaExpense['description'])?></h4><p><?=e($iaExpense['counterparty'].' · '.dateDe($iaExpense['document_date']).' · '.euro((int)$iaExpense['amount_cents']))?></p><a class="btn btn-outline theme-secondary" data-invoice-assignment-choose href="<?=e($iaUrl($iaContext+['assign_page'=>$ia['page'],'assign_expense'=>$iaExpense['id'].':'.$iaExpense['version']]))?>"><?=e($iaText('Diese Ausgabe prüfen'))?></a></article><?php endforeach;?>
<?php if(!$iaCatalogue['rows']):?><p><?=e($iaText('Keine passende aktive Ausgabe gefunden. Suche ändern oder den bereits erfassten Beleg prüfen.'))?></p><?php endif;?>
